import{_ as t,o as e,c as r,ae as o}from"./chunks/framework.Dh1jimFm.js";const u=JSON.parse('{"title":"File Format Reference","description":"","frontmatter":{},"headers":[],"relativePath":"reference/file-formats.md","filePath":"reference/file-formats.md"}'),n={name:"reference/file-formats.md"};function s(i,a,l,d,p,c){return e(),r("div",null,a[0]||(a[0]=[o(`<h1 id="file-format-reference" tabindex="-1">File Format Reference <a class="header-anchor" href="#file-format-reference" aria-label="Permalink to &quot;File Format Reference&quot;">​</a></h1><p>This page documents the <strong>Supervertaler Project Data Format</strong> (Universal Data Exchange Standard).</p><p>If you prefer the repository copy, see: <a href="https://github.com/michaelbeijer/Supervertaler/blob/main/docs/specifications/SUPERVERTALER_DATA_FORMAT.md" target="_blank" rel="noreferrer">https://github.com/michaelbeijer/Supervertaler/blob/main/docs/specifications/SUPERVERTALER_DATA_FORMAT.md</a></p><hr><h1 id="supervertaler-project-data-format" tabindex="-1">Supervertaler Project Data Format <a class="header-anchor" href="#supervertaler-project-data-format" aria-label="Permalink to &quot;Supervertaler Project Data Format&quot;">​</a></h1><h2 id="universal-data-exchange-standard" tabindex="-1">Universal Data Exchange Standard <a class="header-anchor" href="#universal-data-exchange-standard" aria-label="Permalink to &quot;Universal Data Exchange Standard&quot;">​</a></h2><p><strong>Date:</strong> October 14, 2025<br><strong>Version:</strong> 1.0<br><strong>Status:</strong> Implemented</p><hr><h2 id="overview" tabindex="-1">Overview <a class="header-anchor" href="#overview" aria-label="Permalink to &quot;Overview&quot;">​</a></h2><p>The <strong>Supervertaler Project Data Format</strong> is a unified, comprehensive data structure available in two file formats (DOCX and TSV). It serves as the standard for data exchange, archiving, and specialized workflows.</p><hr><h2 id="core-format-specification" tabindex="-1">Core Format Specification <a class="header-anchor" href="#core-format-specification" aria-label="Permalink to &quot;Core Format Specification&quot;">​</a></h2><h3 id="column-structure-version-1-0" tabindex="-1">Column Structure (Version 1.0) <a class="header-anchor" href="#column-structure-version-1-0" aria-label="Permalink to &quot;Column Structure (Version 1.0)&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Column</th><th>Type</th><th>Description</th><th>Required</th></tr></thead><tbody><tr><td><strong>ID</strong></td><td>Integer</td><td>Segment identifier</td><td>✅ Yes</td></tr><tr><td><strong>Status</strong></td><td>String</td><td>Translation status (untranslated, draft, translated, approved, locked)</td><td>✅ Yes</td></tr><tr><td><strong>Source</strong></td><td>String</td><td>Source text</td><td>✅ Yes</td></tr><tr><td><strong>Target</strong></td><td>String</td><td>Target text</td><td>✅ Yes</td></tr><tr><td><strong>Paragraph</strong></td><td>Integer</td><td>Original paragraph ID</td><td>✅ Yes</td></tr><tr><td><strong>Notes</strong></td><td>String</td><td>Translator/proofreader notes</td><td>⚪ Optional</td></tr></tbody></table><h3 id="file-formats" tabindex="-1">File Formats <a class="header-anchor" href="#file-formats" aria-label="Permalink to &quot;File Formats&quot;">​</a></h3><h4 id="_1-docx-format" tabindex="-1">1. DOCX Format <a class="header-anchor" href="#_1-docx-format" aria-label="Permalink to &quot;1. DOCX Format&quot;">​</a></h4><ul><li><strong>Structure:</strong> Word table with 6 columns</li><li><strong>Style:</strong> &quot;Light Grid Accent 1&quot;</li><li><strong>Headers:</strong> Bold text</li><li><strong>Use case:</strong> Review, printing, Word-based workflows</li></ul><h4 id="_2-tsv-format" tabindex="-1">2. TSV Format <a class="header-anchor" href="#_2-tsv-format" aria-label="Permalink to &quot;2. TSV Format&quot;">​</a></h4><ul><li><strong>Structure:</strong> Tab-separated values</li><li><strong>Encoding:</strong> UTF-8</li><li><strong>Header row:</strong> Column names</li><li><strong>Use case:</strong> Excel analysis, scripting, data processing</li></ul><hr><h2 id="current-implementation" tabindex="-1">Current Implementation <a class="header-anchor" href="#current-implementation" aria-label="Permalink to &quot;Current Implementation&quot;">​</a></h2><h3 id="export" tabindex="-1">Export <a class="header-anchor" href="#export" aria-label="Permalink to &quot;Export&quot;">​</a></h3><p><strong>Menu:</strong> Export &gt; Supervertaler project data (DOCX/TSV)</p><p><strong>Methods:</strong></p><ul><li><code>export_supervertaler_data()</code> - Main entry point with format dialog</li><li><code>export_bilingual_docx_full()</code> - DOCX export with all 6 columns</li><li><code>export_tsv()</code> - TSV export with all 6 columns</li></ul><h3 id="import" tabindex="-1">Import <a class="header-anchor" href="#import" aria-label="Permalink to &quot;Import&quot;">​</a></h3><p><strong>Status:</strong> Not yet implemented (planned feature)</p><p><strong>Planned functionality:</strong></p><ul><li>Import DOCX or TSV files in Supervertaler project data format</li><li>Auto-detect format based on file extension</li><li>Validate column structure</li><li>Reimport with full metadata preservation</li></ul><hr><h2 id="future-extensions" tabindex="-1">Future Extensions <a class="header-anchor" href="#future-extensions" aria-label="Permalink to &quot;Future Extensions&quot;">​</a></h2><h3 id="_1-proofreading-workflow-📝" tabindex="-1">1. Proofreading Workflow 📝 <a class="header-anchor" href="#_1-proofreading-workflow-📝" aria-label="Permalink to &quot;1. Proofreading Workflow 📝&quot;">​</a></h3><p><strong>Concept:</strong> Round-trip translation → proofreading → reimport</p><p><strong>Export for Proofreading:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Menu: Export &gt; For proofreading (DOCX/TSV)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Format: Same 6-column structure</span></span>
<span class="line"><span>Special handling:</span></span>
<span class="line"><span>  - Lock translated segments (status = locked)</span></span>
<span class="line"><span>  - Add &quot;Proofread by: ___&quot; field</span></span>
<span class="line"><span>  - Include proofreading instructions</span></span></code></pre></div><p><strong>Import from Proofreading:</strong></p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>Menu: Import &gt; Proofread document (DOCX/TSV)</span></span>
<span class="line"><span></span></span>
<span class="line"><span>Features:</span></span>
<span class="line"><span>  - Compare with original segments</span></span>
<span class="line"><span>  - Track proofreader changes</span></span>
<span class="line"><span>  - Update targets with proofread versions</span></span>
<span class="line"><span>  - Preserve status and notes</span></span>
<span class="line"><span>  - Generate change report</span></span></code></pre></div><h3 id="_2-glossary-integration-📚" tabindex="-1">2. Glossary Integration 📚 <a class="header-anchor" href="#_2-glossary-integration-📚" aria-label="Permalink to &quot;2. Glossary Integration 📚&quot;">​</a></h3><p><strong>Concept:</strong> Export segments as glossary entries</p><h3 id="_3-qa-workflow-🔍" tabindex="-1">3. QA Workflow 🔍 <a class="header-anchor" href="#_3-qa-workflow-🔍" aria-label="Permalink to &quot;3. QA Workflow 🔍&quot;">​</a></h3><p><strong>Concept:</strong> Export for quality assurance checks</p><h3 id="_4-segment-filtering-partial-export-🎯" tabindex="-1">4. Segment Filtering &amp; Partial Export 🎯 <a class="header-anchor" href="#_4-segment-filtering-partial-export-🎯" aria-label="Permalink to &quot;4. Segment Filtering &amp; Partial Export 🎯&quot;">​</a></h3><p><strong>Concept:</strong> Export subsets based on filters</p><h3 id="_5-version-comparison-🔄" tabindex="-1">5. Version Comparison 🔄 <a class="header-anchor" href="#_5-version-comparison-🔄" aria-label="Permalink to &quot;5. Version Comparison 🔄&quot;">​</a></h3><p><strong>Concept:</strong> Compare two versions of same document</p><h3 id="_6-collaborative-translation-👥" tabindex="-1">6. Collaborative Translation 👥 <a class="header-anchor" href="#_6-collaborative-translation-👥" aria-label="Permalink to &quot;6. Collaborative Translation 👥&quot;">​</a></h3><p><strong>Concept:</strong> Split project among multiple translators</p>`,47)]))}const g=t(n,[["render",s]]);export{u as __pageData,g as default};
